import type { IconData } from "./material/types";

/* Custom icons: your own SVGs, built in by tools/icons/build.mjs. Each is the inner markup of a
   24×24 SVG, cleaned by the build (shapes only, drawn in currentColor), so it's safe to insert.
   module state: filled at build time, never while the page runs. */
/* @icons:start generated by tools/icons/build.mjs from your icon SVGs; edit the SVGs, not this */
export const ICONS: Record<string, string> = {};
/* @icons:end */

// @icons:start generated by tools/icons/build.mjs
/** Names of the custom icons (tools/icons/build.mjs). Empty (never) until you add some. */
export type CustomIconName = never;
/** Names of your custom icons, sorted. */
export const customIcons: readonly CustomIconName[] = /* @__PURE__ */ Object.freeze([]);
// @icons:end

export function hasIcon(name: unknown): name is string {
  return typeof name === "string" && Object.prototype.hasOwnProperty.call(ICONS, name);
}

/* Material Symbols by name. Components import the icons they draw (src/material/builtin.ts), so a bundle keeps only
   those. A name drawn as a string loads on first use: the components' icons from a small chunk (src/material/named.ts),
   any other from the full set (src/material/icons.ts). Names a project registers win over both. */
// module state: icons by name, the same for every request; the two loads below run once per process (a failed one is
// forgotten, so the next call tries again: a network blip, or a deploy that removed the old chunk).
const NAMED = new Map<string, IconData>();
let loading: Promise<void> | undefined;
let loadingNamed: Promise<void> | undefined;
// module state: the names that came from a load rather than registerIcons, the same for every request. The server
// never loads them, so a hydration leaves them out even when this page loaded them already (for an island hydrated
// after another).
const LOADED = new Set<string>();
const loaded = (v: IconData) => { if (!NAMED.has(v.name)) { NAMED.set(v.name, v); LOADED.add(v.name); } };
// The two chunks, as an object so a test can make a load fail (Icon's IconLoad.test.tsx).
// serupa.iife.js swaps `all` for a script tag (src/browser.ts): an IIFE can't split, so the table is a script of its own.
export const iconChunks: { named: () => Promise<{ NAMED_ICONS: readonly IconData[] }>; all: () => Promise<Readonly<Record<string, unknown>>> } =
  { named: () => import("./material/named"), all: () => import("./material/icons") };

/** Loads the icon for a name (Icon calls it when it meets a name it doesn't know yet): the components' own icons first,
 * from a small chunk, then every Material Symbol. Resolves to the icon, or undefined if no icon has that name. */
export function loadIcon(name: string): Promise<IconData | undefined> {
  const found = () => NAMED.get(name);
  if (!loadingNamed) loadingNamed = iconChunks.named().then((m) => {
    for (const v of m.NAMED_ICONS) loaded(v);
  }).catch((err: unknown) => { loadingNamed = undefined; throw err; });
  return loadingNamed.then(() => found() || loadAllIcons().then(found));
}

/** Loads every Material Symbol so its name works (once; Icon calls it when it meets a name it doesn't know yet). */
export function loadAllIcons(): Promise<void> {
  return loading || (loading = iconChunks.all().then((all) => {
    for (const v of Object.values(all)) if (isIconData(v)) loaded(v);
  }).catch((err: unknown) => { loading = undefined; throw err; }));
}

/** Adds icons that work by name. Every Material Symbol already does; use this for an icon of your own in the same shape
 * (`{ name, d }`, drawn on Material's 960-unit grid): `registerIcons(MyIcon)` or a whole module. To draw every icon on
 * the first render (server rendering, say), register the full set first: `registerIcons(await import("serupa-ds/icons"))`. */
export function registerIcons(...icons: Array<IconData | Readonly<Record<string, IconData>>>): void {
  for (const x of icons) {
    for (const v of isIconData(x) ? [x] : Object.values(x)) if (isIconData(v)) { NAMED.set(v.name, v); LOADED.delete(v.name); }
  }
}

/** The Material Symbol for a name, if it is registered or already loaded. */
export function getIcon(name: string): IconData | undefined {
  return NAMED.get(name);
}

/** The Material Symbol for a name if it is registered: what a server draws, so what a hydration must draw too. */
export function getRegisteredIcon(name: string): IconData | undefined {
  return LOADED.has(name) ? undefined : NAMED.get(name);
}

export function isIconData(x: unknown): x is IconData {
  return !!x && typeof x === "object" && typeof (x as IconData).name === "string" && typeof (x as IconData).d === "string";
}
